ImportStep.heading:
.input {$featureCount :integer}
.match $featureCount
one {{How do you want to upload this {$featureCount} change to OpenStreetMap?}}
*   {{How do you want to upload these {$featureCount} changes to OpenStreetMap?}}

ImportStep.lock_notice:
.input {$count :integer}
.match $count
one {{Once you choose an option, this {$count} dataset will be “locked”, to prevent other importers from uploading the same content. Your OSM username {#avatar/} {#user/} will be temporarily stored and visible to other importers.}}
*   {{Once you choose an option, these {$count} datasets will be “locked”, to prevent other importers from uploading the same content. Your OSM username {#avatar/} {#user/} will be temporarily stored and visible to other importers.}}

ProjectPage.download_failed:
.input {$count :integer}
.match $count
one {{{$count} dataset could not be downloaded}}
*   {{{$count} datasets could not be downloaded}}

SelectDatasetsStep.count:
.input {$count :integer}
.match $count
0   {{No datasets selected}}
one {{{$count} dataset selected}}
*   {{{$count} datasets selected}}

SelectFeaturesStep.count:
.input {$count :integer}
.match $count
0   {{No features selected}}
one {{{$count} feature selected}}
*   {{{$count} features selected}}

WarningsPage.count:
.input {$count :integer}
.match $count
one {{{$count} warning from the last run}}
*   {{{$count} warnings from the last run}}
